import { useMemo } from 'react'

import { useSuspenseQuery } from '@tanstack/react-query'

import { getLearningHistoriesBySha, type LearningHistoryRow } from '@/api/learningHistories'
import { useAuth } from '@/contexts/AuthContext'

import { useLearningHistoryBatch } from './useLearningHistoryBatch'

export type LearningHistorySummary = {
  histories: LearningHistoryRow[]
  cntTries: number
  cntTotal: number
  cntPass: number
  cntFail: number
  passRate: number
  duration: number
}

export function useLearningHistorySummary(sha: string | undefined) {
  const { user } = useAuth()
  const batch = useLearningHistoryBatch()
  // 배치로 미리 로드된 집계가 있으면 개별 조회를 생략한다 (목록/뱃지 용도).
  const batched = sha ? batch?.get(sha) : undefined

  // batched 경로는 원본 행이 필요 없어 []를 반환한다. 이 []가 raw 경로와 같은
  // 캐시 키를 쓰면, batch 화면 방문 후 batch 없는 화면에서 빈 histories를 읽게 되므로
  // 키에 'agg'/'raw' 구분자를 두어 캐시 오염을 막는다.
  const { data: histories } = useSuspenseQuery({
    queryKey: ['learningHistorySummary', sha, user?.id, batched ? 'agg' : 'raw'],
    queryFn: async () => {
      if (!sha || batched) return []
      return getLearningHistoriesBySha(sha, user?.id)
    },
    staleTime: 1000 * 60 * 5,
  })

  const summary = useMemo<LearningHistorySummary>(() => {
    // 배치 집계가 있으면 원본 행 없이 집계값만 반환한다.
    // (배치 하위에서는 line별 histories를 소비하는 곳이 없다.)
    if (batched) {
      const { cntTries, cntTotal, cntPass, cntFail, passRate, duration } = batched
      return { histories: [], cntTries, cntTotal, cntPass, cntFail, passRate, duration }
    }

    const itemHistories = histories.filter((h) => h.type !== 'fin')
    const finHistories = histories.filter((h) => h.type === 'fin')
    const cntTries = finHistories.length
    const cntPass = itemHistories.filter((h) => h.type === 'pass').length
    const cntFail = itemHistories.filter((h) => h.type === 'fail').length
    const cntTotal = cntPass + cntFail
    const passRate = cntTotal > 0 ? (cntPass / cntTotal) * 100 : 0
    const duration = finHistories.reduce((sum, h) => sum + h.duration, 0)

    return { histories, cntTries, cntTotal, cntPass, cntFail, passRate, duration }
  }, [histories, batched])

  return summary
}
