import { createContext, useContext, useMemo, type ReactNode } from 'react'

import { useSuspenseQuery } from '@tanstack/react-query'

import { getLearningSummaries, type LearningSummary } from '@/api/learningHistories'
import { useAuth } from '@/contexts/AuthContext'

export type LearningHistoryBatchMap = Map<string, LearningSummary>

const LearningHistoryBatchContext = createContext<LearningHistoryBatchMap | null>(null)

/**
 * 배치로 미리 로드된 학습 이력 집계 맵을 반환한다.
 * Provider 밖에서는 null이며, 이 경우 개별 조회로 폴백한다.
 */
// eslint-disable-next-line react-refresh/only-export-components
export function useLearningHistoryBatch(): LearningHistoryBatchMap | null {
  return useContext(LearningHistoryBatchContext)
}

export type LearningHistoryBatchProviderProps = {
  shas: string[]
  children: ReactNode
}

/**
 * 주어진 sha 목록의 학습 이력 집계를 단일 RPC로 로드하여 sha별 맵으로 제공한다.
 * 집계를 DB에서 수행하므로 목록이 커져도 1000행 제한에 걸리지 않는다.
 */
export function LearningHistoryBatchProvider(props: LearningHistoryBatchProviderProps) {
  const { shas, children } = props
  const { user } = useAuth()

  const sortedShas = useMemo(() => [...new Set(shas)].sort(), [shas])

  const { data } = useSuspenseQuery({
    queryKey: ['learningHistoryBatch', sortedShas, user?.id],
    queryFn: async () => getLearningSummaries(sortedShas),
    staleTime: 1000 * 60 * 5,
  })

  const map = useMemo<LearningHistoryBatchMap>(() => {
    const grouped: LearningHistoryBatchMap = new Map()
    // 이력 없는 sha도 zero 집계로 미리 채워, 개별 폴백 조회(N+1)를 막는다.
    for (const sha of sortedShas) {
      grouped.set(sha, {
        sha,
        cntTries: 0,
        cntPass: 0,
        cntFail: 0,
        cntTotal: 0,
        passRate: 0,
        duration: 0,
      })
    }
    for (const summary of data) grouped.set(summary.sha, summary)
    return grouped
  }, [data, sortedShas])

  return (
    <LearningHistoryBatchContext.Provider value={map}>
      {children}
    </LearningHistoryBatchContext.Provider>
  )
}
